<script setup lang="ts">
import PaperEditor from '../components/PaperEditor.vue'
import { ref,computed } from 'vue'
import { usePlatform } from '../stores/platform'
import { professions } from '../mocks/seed'
import { validatePaper } from '../domain/rules'
import type { Paper } from '../domain/types'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
const s=usePlatform();const search=ref(''),mode=ref('全部试卷'),open=ref(false),detail=ref<Paper|null>(null),form=ref({name:'装配工三级理论认定试卷',count:20,seed:2026,ab:true,difficulty:'不限',profession:professions[0]!,overlap:20}),error=ref('')
const papers=computed(()=>s.data.papers.filter(p=>(!search.value||p.name.includes(search.value))&&(mode.value==='全部试卷'||p.status===mode.value)))
function generate(){error.value='';try{const id=s.newPapers(form.value.name,form.value.count,form.value.seed,form.value.ab,form.value.difficulty,form.value.profession,form.value.overlap);open.value=false;detail.value=s.data.papers.find(p=>p.id===id)!}catch(e){error.value=e instanceof Error?e.message:'组卷失败'}}
function check(p:Paper){s.run(()=>{p.report=validatePaper(p.questions);s.audit('组卷管理','复核试卷',p.id);s.notify('试卷质量校验通过')})}
function printPaper(){window.print()}
</script>
<template><PageHead title="组卷管理" subtitle="按标准比重配置试卷，用可解释的规则完成抽题、校验与定版。" eyebrow="题库应用 / 试卷中心"><RouterLink class="button" to="/papers/rules">标准比重配置</RouterLink><RouterLink v-if="s.can('affairs')" class="button" to="/protocol/papers">试卷配发记录</RouterLink><RouterLink class="button" to="/bank/questions"><Icon name="ListChecks" :size="16"/>固定选题组卷</RouterLink><button class="button primary" @click="open=true;error='' "><Icon name="WandSparkles" :size="17"/>新建规则组卷</button></PageHead>
<div class="info-banner"><span class="banner-icon"><Icon name="Layers" :size="25"/></span><div><strong>1 + X + Y 组合组卷</strong><p>母题库提供统一基础，子题库体现专业特色，通用题库支持共享复用。</p></div><div class="source-chips"><span>母题库 50%</span><b>+</b><span>子题库 30%</span><b>+</b><span>通用题库 20%</span></div></div>
<section class="panel"><div class="tabs"><button v-for="t in ['全部试卷','草稿','已冻结','已配发']" :class="{active:mode===t}" @click="mode=t">{{t}}</button></div><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="17"/><input v-model="search" placeholder="搜索试卷名称…"/></div><span class="filter-meta">共{{papers.length}}套 · 冻结后可配发</span></div><div class="table-scroll"><table><thead><tr><th>试卷名称</th><th>组卷方案</th><th>题量 / 总分</th><th>AB重复率</th><th>版本 / 状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in papers"><td><button class="cell-link" @click="detail=p">{{p.name}}</button><small>{{p.id}} · {{p.created}}</small></td><td>{{p.rule}}</td><td>{{p.questions.length}} 道<small>{{Math.round(p.questions.reduce((a,q)=>a+q.score,0))}} 分</small></td><td><span class="text-green">{{p.overlap}}%</span><small>按稳定题号</small></td><td><Badge :text="p.status"/><small>V{{p.version}}</small></td><td><div class="action-group"><button class="text-button" @click="detail=p">预览</button><button v-if="p.status==='草稿'" class="text-button" @click="s.run(()=>s.freezePaper(p.id))">冻结</button><RouterLink v-else-if="s.can('affairs')" class="text-button" to="/affairs/sessions">配发</RouterLink></div></td></tr></tbody></table></div><Empty v-if="!papers.length"/></section>
<div class="bottom-grid spaced"><section class="panel"><div class="panel-head"><h3>组卷质量检查</h3><Icon name="ShieldCheck" :size="18"/></div><div class="check-grid"><p v-for="t in ['仅使用已入库资源','卷内按题号去重','总分与题量一致','题库来源配额校验','冻结题面与答案版本','缺题明确提示，不降低规则']"><Icon name="CircleCheck" :size="17"/>{{t}}</p></div></section><section class="panel"><div class="panel-head"><h3>组卷规则说明</h3></div><div class="aside-copy"><p>标准卷：单选50%、多选25%、判断25%，总分100分。题型总分分别为40、40、20。</p><p>AB重复率＝共享题号数÷较短卷题数。当前算法优先生成零重复AB卷；库存不足时返回明确提示。</p></div></section></div>
<Modal v-if="open" title="配置规则并生成试卷" wide @close="open=false"><div class="form-grid"><label class="span-two">试卷名称<input v-model="form.name"/></label><label>职业工种<select v-model="form.profession"><option v-for="p in professions">{{p}}</option></select></label><label>试题难度<select v-model="form.difficulty"><option>不限</option><option>容易</option><option>中等</option><option>较难</option></select></label><label>试卷题量（4的倍数）<input v-model.number="form.count" type="number" min="4" max="100" step="4"/></label><label>抽题种子<input v-model.number="form.seed" type="number"/></label><label>试卷模式<select v-model="form.ab"><option :value="true">生成 A / B 两套卷</option><option :value="false">生成单套卷</option></select></label><label>AB最大重复率（%）<input v-model.number="form.overlap" type="number" min="0" max="100"/></label></div><div class="rule-breakdown"><div><span>单选题</span><strong>{{form.count/2}} <small>道 / 40分</small></strong></div><div><span>多选题</span><strong>{{form.count/4}} <small>道 / 40分</small></strong></div><div><span>判断题</span><strong>{{form.count/4}} <small>道 / 20分</small></strong></div></div><div class="notice">按题型分层执行50%/30%/20%来源比重，余数按小数部分排序分配。使用固定种子可复现抽题结果，生成后独立校验。</div><div v-if="error" class="notice warning"><Icon name="CircleAlert" :size="18"/>{{error}}</div><template #footer><button class="button" @click="open=false">取消</button><button class="button primary" @click="generate"><Icon name="WandSparkles" :size="16"/>生成并校验</button></template></Modal>
<Modal v-if="detail" :title="detail.name" wide @close="detail=null"><div class="print-header"><h2>{{detail.name}}</h2><p>演示试卷 · V{{detail.version}} · 总分100分 · 不用于正式认定</p></div><div class="tag-list"><Badge :text="detail.status"/><span>{{detail.questions.length}}道</span><span>V{{detail.version}}</span></div><PaperEditor v-if="detail.status==='草稿'" :key="detail.id+detail.version" :paper="detail"/><div class="quality-report"><p v-for="r in detail.report"><Icon name="CircleCheck" :size="15"/>{{r}}</p></div><div v-for="(item,i) in detail.questions" class="paper-question"><div><span>{{i+1}}.</span><strong>{{item.question.title}}</strong><small>{{item.question.type}} · {{Number(item.score.toFixed(2))}}分</small></div><p v-for="(o,oi) in item.question.options">{{String.fromCharCode(65+oi)}}. {{o}}</p><div v-if="item.question.kind==='技能'"><p>考生准备：{{item.question.preparation}}</p><p>考场准备：{{item.question.venue}}</p><p v-for="r in item.question.rubric">{{r.label}}（{{r.max}}分）</p></div></div><template #footer><button class="button" @click="check(detail!)">重新校验</button><button class="button" @click="printPaper"><Icon name="Printer" :size="16"/>打印考生卷</button><button v-if="detail.status==='草稿'" class="button primary" @click="s.run(()=>s.freezePaper(detail!.id))">冻结试卷</button></template></Modal>
</template>
